mkitem!{mkstruct!{# [doc = " The `GatherLocalsVisitor` is responsible for initializing local variable types"] # [doc = " in the [`ty::TypeckResults`] for all subpatterns in statements and expressions"] # [doc = " like `let`, `match`, and params of function bodies. It also adds `Sized` bounds"] # [doc = " for these types (with exceptions for unsized feature gates like `unsized_fn_params`)."] # [doc = ""] # [doc = " Failure to visit locals will cause an ICE in writeback when the local's type is"] # [doc = " resolved. Visiting locals twice will ICE in the `GatherLocalsVisitor`, since it"] # [doc = " will overwrite the type previously stored in the local."] pub (super) struct GatherLocalsVisitor < 'a , 'tcx > { fcx : & 'a FnCtxt < 'a , 'tcx > , outermost_fn_param_pat : Option < (Span , HirId) > , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > GatherLocalsVisitor < 'a , 'tcx > { pub (crate) fn gather_from_local (fcx : & 'a FnCtxt < 'a , 'tcx > , local : & 'tcx hir :: LetStmt < 'tcx >) { let mut visitor = GatherLocalsVisitor { fcx , outermost_fn_param_pat : None } ; visitor . declare (local . into ()) ; visitor . visit_pat (local . pat) ; } pub (crate) fn gather_from_let_expr (fcx : & 'a FnCtxt < 'a , 'tcx > , let_expr : & 'tcx hir :: LetExpr < 'tcx > , expr_hir_id : hir :: HirId ,) { let mut visitor = GatherLocalsVisitor { fcx , outermost_fn_param_pat : None } ; visitor . declare ((let_expr , expr_hir_id) . into ()) ; visitor . visit_pat (let_expr . pat) ; } pub (crate) fn gather_from_param (fcx : & 'a FnCtxt < 'a , 'tcx > , param : & 'tcx hir :: Param < 'tcx >) { let mut visitor = GatherLocalsVisitor { fcx , outermost_fn_param_pat : Some ((param . ty_span , param . hir_id)) , } ; visitor . visit_pat (param . pat) ; } pub (crate) fn gather_from_arm (fcx : & 'a FnCtxt < 'a , 'tcx > , local : & 'tcx hir :: Arm < 'tcx >) { let mut visitor = GatherLocalsVisitor { fcx , outermost_fn_param_pat : None } ; visitor . visit_pat (local . pat) ; } fn assign (& mut self , span : Span , nid : HirId , ty_opt : Option < Ty < 'tcx > >) -> Ty < 'tcx > { if let Some (& local) = self . fcx . locals . borrow_mut () . get (& nid) { self . fcx . dcx () . span_delayed_bug (span , "evaluated expression more than once") ; return local ; } match ty_opt { None => { let var_ty = self . fcx . next_ty_var (span) ; self . fcx . locals . borrow_mut () . insert (nid , var_ty) ; var_ty } Some (typ) => { self . fcx . locals . borrow_mut () . insert (nid , typ) ; typ } } } # [doc = " Allocates a type for a declaration, which may have a type annotation. If it does have"] # [doc = " a type annotation, then the [`Ty`] stored will be the resolved type. This may be found"] # [doc = " again during type checking by querying [`FnCtxt::local_ty`] for the same hir_id."] fn declare (& mut self , decl : Declaration < 'tcx >) { let local_ty = match decl . ty { Some (ref ty) => { let o_ty = self . fcx . lower_ty (ty) ; let c_ty = self . fcx . infcx . canonicalize_user_type_annotation (ty :: UserType :: new_with_bounds (ty :: UserTypeKind :: Ty (o_ty . raw) , self . fcx . collect_impl_trait_clauses_from_hir_ty (ty) ,) ,) ; debug ! ("visit_local: ty.hir_id={:?} o_ty={:?} c_ty={:?}" , ty . hir_id , o_ty , c_ty) ; self . fcx . typeck_results . borrow_mut () . user_provided_types_mut () . insert (ty . hir_id , c_ty) ; Some (o_ty . normalized) } None => None , } ; self . assign (decl . span , decl . hir_id , local_ty) ; debug ! ("local variable {:?} is assigned type {}" , decl . pat , self . fcx . ty_to_string (* self . fcx . locals . borrow () . get (& decl . hir_id) . unwrap ())) ; } }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > Visitor < 'tcx > for GatherLocalsVisitor < 'a , 'tcx > { fn visit_local (& mut self , local : & 'tcx hir :: LetStmt < 'tcx >) { self . declare (local . into ()) ; intravisit :: walk_local (self , local) } fn visit_expr (& mut self , expr : & 'tcx hir :: Expr < 'tcx >) { if let hir :: ExprKind :: Let (let_expr) = expr . kind { self . declare ((let_expr , expr . hir_id) . into ()) ; } intravisit :: walk_expr (self , expr) } fn visit_pat (& mut self , p : & 'tcx hir :: Pat < 'tcx >) { if let PatKind :: Binding (_ , _ , ident , _) = p . kind { let var_ty = self . assign (p . span , p . hir_id , None) ; if let Some ((ty_span , hir_id)) = self . outermost_fn_param_pat { if ! self . fcx . tcx . features () . unsized_fn_params () { self . fcx . require_type_is_sized (var_ty , ty_span , ObligationCauseCode :: SizedArgumentType (if ty_span == ident . span && self . fcx . tcx . is_closure_like (self . fcx . body_id . into ()) { None } else { Some (hir_id) } ,) ,) ; } } else { self . fcx . require_type_is_sized (var_ty , p . span , ObligationCauseCode :: VariableType (p . hir_id) ,) ; } debug ! ("pattern binding {} is assigned to {} with type {:?}" , ident , self . fcx . ty_to_string (* self . fcx . locals . borrow () . get (& p . hir_id) . unwrap ()) , var_ty) ; } let old_outermost_fn_param_pat = self . outermost_fn_param_pat . take () ; if let PatKind :: Guard (subpat , _) = p . kind { self . visit_pat (subpat) ; } else { intravisit :: walk_pat (self , p) ; } self . outermost_fn_param_pat = old_outermost_fn_param_pat ; } fn visit_fn (& mut self , _ : intravisit :: FnKind < 'tcx > , _ : & 'tcx hir :: FnDecl < 'tcx > , _ : hir :: BodyId , _ : Span , _ : LocalDefId ,) { } }}}